function Hero() {
  return (
    <section className="hero">
      <h1>Win Every Gig with AI</h1>

      <p>
        Find clients faster with AI-powered tools that help you rank your
        profile, optimize gigs, and generate winning proposals.
      </p>

      <div className="hero-buttons">
        <button className="btn-primary">
          Get Started Free
        </button>

        <button className="btn-secondary">
          Watch Demo
        </button>
      </div>
    </section>
  );
}

export default Hero;
